import{_ as e,o as a,c as s,a3 as i}from"./chunks/framework.Ki30n65y.js";const k=JSON.parse('{"title":"HTTPS and networking","description":"","frontmatter":{},"headers":[],"relativePath":"install/https-and-networking.md","filePath":"install/https-and-networking.md"}'),o={name:"install/https-and-networking.md"};function n(r,t,d,p,l,h){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="https-and-networking" tabindex="-1">HTTPS and networking <a class="header-anchor" href="#https-and-networking" aria-label="Permalink to &quot;HTTPS and networking&quot;">​</a></h1><p>DepGate is usually installed inside a company network: with a certificate from the company CA, behind a load balancer, and with outbound traffic through a proxy. This page covers each of those setups.</p><h2 id="https-in-depgate" tabindex="-1">HTTPS in DepGate <a class="header-anchor" href="#https-in-depgate" aria-label="Permalink to &quot;HTTPS in DepGate&quot;">​</a></h2><p>By default DepGate terminates TLS itself:</p><ul><li>HTTPS on host port <strong>443</strong>, using <code>certs/tls.crt</code> and <code>certs/tls.key</code>.</li><li>Host port <strong>80</strong> redirects every request to the same path on <code>GATEWAY_URL</code>.</li></ul><p><strong>Renewing the certificate.</strong> Overwrite <code>tls.crt</code> and <code>tls.key</code>. DepGate picks up the new files within a minute, without a restart. To apply them at once:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kill</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HUP</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span></span></code></pre></div><p><strong>Certificates inside a company network.</strong> A server without internet access cannot obtain a public certificate. Use one issued by your company CA for the exact host name in <code>GATEWAY_URL</code>, with the intermediate certificates appended to <code>tls.crt</code>.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>HTTPS_PORT</code></td><td><code>443</code></td><td>Host port for HTTPS.</td></tr><tr><td><code>HTTP_PORT</code></td><td><code>80</code></td><td>Host port for the redirect.</td></tr><tr><td><code>HTTP_REDIRECT</code></td><td><code>true</code></td><td><code>false</code> closes the HTTP port instead of redirecting.</td></tr></tbody></table><h2 id="behind-your-own-tls-proxy" tabindex="-1">Behind your own TLS proxy <a class="header-anchor" href="#behind-your-own-tls-proxy" aria-label="Permalink to &quot;Behind your own TLS proxy&quot;">​</a></h2><p>If a load balancer or reverse proxy terminates TLS, set <code>DISABLE_SSL=true</code> in <code>.env</code>. DepGate then serves plain HTTP on port 80 and needs no certificate.</p><ul><li>Keep <code>GATEWAY_URL</code> set to the proxy&#39;s <code>https://</code> address.</li><li>If the proxy runs on the same host, set <code>HTTP_BIND=127.0.0.1</code> so nothing can reach DepGate around the proxy. If the proxy needs port 443 on that host, also set <code>HTTPS_PORT=127.0.0.1:8443</code>.</li><li>DepGate trusts one proxy hop for client addresses (<code>TRUST_PROXY=1</code>). Set the number of hops if there are more.</li></ul><p>Configure the proxy to pass the <code>Host</code> header and <code>X-Forwarded-For</code>, allow large request bodies, and stream downloads without buffering. For nginx:</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">location</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> / </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_pass </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://depgate-host:80;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Host $host;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Forwarded-For $proxy_add_x_forwarded_for;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Forwarded-Proto https;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    client_max_body_size </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1g</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_buffering </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">off</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_read_timeout </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300s</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="corporate-outbound-proxy" tabindex="-1">Corporate outbound proxy <a class="header-anchor" href="#corporate-outbound-proxy" aria-label="Permalink to &quot;Corporate outbound proxy&quot;">​</a></h2><p>DepGate fetches packages, vulnerability data and feeds from the internet. To send that traffic through an HTTP proxy, add to <code>.env</code>:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NODE_USE_ENV_PROXY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HTTP_PROXY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=http://proxy.example.com:3128</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HTTPS_PROXY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=http://proxy.example.com:3128</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NO_PROXY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=localhost,127.0.0.1,.internal.example.com</span></span></code></pre></div><ul><li>Put credentials in the URL (<code>http://user:password@proxy.example.com:3128</code>) and URL-encode special characters.</li><li>List internal hosts in <code>NO_PROXY</code>: internal registries, webhook endpoints and the database.</li><li>Email (SMTP) does not use the proxy.</li><li>If the proxy inspects TLS, add its CA certificate to <code>certs/ca.crt</code>. DepGate trusts that file for every outgoing connection.</li></ul><h2 id="trusting-your-ca-in-package-clients" tabindex="-1">Trusting your CA in package clients <a class="header-anchor" href="#trusting-your-ca-in-package-clients" aria-label="Permalink to &quot;Trusting your CA in package clients&quot;">​</a></h2><p>Clients must trust the certificate DepGate presents. Most use the operating system&#39;s trust store, which usually already holds the company CA. Some need it configured:</p><table tabindex="0"><thead><tr><th>Client</th><th>How to trust the company CA</th></tr></thead><tbody><tr><td>npm, Yarn, pnpm</td><td><code>npm config set cafile /path/to/company-ca.pem</code>, or the <code>NODE_EXTRA_CA_CERTS</code> environment variable</td></tr><tr><td>pip</td><td><code>pip config set global.cert /path/to/company-ca.pem</code>, or <code>REQUESTS_CA_BUNDLE</code></td></tr><tr><td>Maven, Gradle</td><td>Import into the Java truststore: <code>keytool -importcert -cacerts -alias company-ca -file company-ca.pem</code></td></tr><tr><td>Go, Cargo, Composer, NuGet, RubyGems</td><td>Operating system trust store</td></tr></tbody></table><h2 id="air-gapped-installations" tabindex="-1">Air-gapped installations <a class="header-anchor" href="#air-gapped-installations" aria-label="Permalink to &quot;Air-gapped installations&quot;">​</a></h2><p>DepGate can run with no inbound internet access. It still needs outbound access to the registries it proxies and to its data sources. Where that is not allowed:</p><ul><li>Point the repositories at internal mirrors (Artifactory, Nexus) instead of the public registries.</li><li>Point <code>EPSS_FEED_URL</code> at an internal copy of the daily EPSS file, and <code>MALICIOUS_FEED_URL</code> / <code>MALICIOUS_FEED_ARCHIVE_URL</code> at a mirror of the malware feed.</li><li>Without vulnerability data, Vulnerability policies cannot match. Plan for an internal OSV mirror (<code>OSV_API_URL</code>).</li></ul><h2 id="what-is-exposed" tabindex="-1">What is exposed <a class="header-anchor" href="#what-is-exposed" aria-label="Permalink to &quot;What is exposed&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Port</th><th>Exposed</th><th>Serves</th></tr></thead><tbody><tr><td>443</td><td>Yes</td><td>Web interface, API and registries over HTTPS.</td></tr><tr><td>80</td><td>Yes</td><td>Redirect to HTTPS, or the whole application with <code>DISABLE_SSL=true</code>.</td></tr><tr><td>9464</td><td>No (private Compose network)</td><td><code>/metrics</code>, <code>/healthz</code>, <code>/readyz</code>.</td></tr></tbody></table><p>The application runs as an unprivileged user. The optional database stack publishes PostgreSQL and Redis only on the loopback interface.</p>`,27)])])}const u=e(o,[["render",n]]);export{k as __pageData,u as default};
